class Solution {
    public long maximumSumScore(int[] nums) {
        long total = 0;
        for (int x : nums) total += x;
        long pref = 0;
        long ans = Long.MIN_VALUE;
        for (int x : nums) {
            pref += x;
            long suff = total - pref + x;
            ans = Math.max(ans, Math.max(pref, suff));
        }
        return ans;
    }
}

