var maximumSumScore = function(nums) {
    let total = 0n;
    for (const x of nums) total += BigInt(x);
    let pref = 0n;
    let ans = -1000000000000000000n;
    for (const x of nums) {
        pref += BigInt(x);
        const suff = total - pref + BigInt(x);
        if (pref > ans) ans = pref;
        if (suff > ans) ans = suff;
    }
    return Number(ans);
};
